const btn = await figma.getNodeByIdAsync("1:28");
const logo = await figma.getNodeByIdAsync("2:16");
const icon = await figma.getNodeByIdAsync("2:3");

function briefNode(n, depth) {
  const pad = "  ".repeat(depth);
  let out = pad + n.type + " \"" + n.name + "\"";
  if ("width" in n) out += " " + Math.round(n.width) + "x" + Math.round(n.height);
  if ("fills" in n && Array.isArray(n.fills)) {
    const f = n.fills.map(x => x.type === "SOLID" ? "SOLID:" + JSON.stringify(x.color) : x.type).join("|");
    if (f) out += " fills[" + f + "]";
  }
  if ("strokes" in n && Array.isArray(n.strokes) && n.strokes.length) out += " strokes:" + JSON.stringify(n.strokes);
  if ("cornerRadius" in n && typeof n.cornerRadius === "number") out += " r=" + n.cornerRadius;
  if (n.type === "TEXT") out += " text=\"" + n.characters + "\" font=" + JSON.stringify(n.fontName) + " size=" + n.fontSize + " color=" + JSON.stringify(n.fills);
  out += "\n";
  if (depth < 3 && "children" in n) {
    for (const c of n.children) out += briefNode(c, depth + 1);
  }
  return out;
}

return "BUTTON:\n" + briefNode(btn, 0) + "\nLOGO:\n" + briefNode(logo, 0) + "\nICON_ARROW_RIGHT:\n" + briefNode(icon, 0);

