  const kids = [];
  const walk = (n, d) => { if (!("children" in n)) return; for (const ch of n.children) {
    kids.push(d + "|" + ch.type + " " + Math.round(ch.width) + "x" + Math.round(ch.height) +
      " F:" + ("fills" in ch ? JSON.stringify(ch.fills).slice(0,100) : "-") +
